/**
 * Run `worker` over `items` with at most `limit` workers in flight, resolving to
 * the worker results in input order.
 *
 * Contract
 * --------
 * - `items` must be an array, `limit` a positive integer and `worker` callable.
 *   Invalid arguments reject with a `TypeError` *before* `worker` is invoked
 *   (validation also happens for empty input).
 * - `worker(item, index, signal)` may return a value, a promise, or throw
 *   synchronously. `items` is never mutated.
 * - At most `limit` workers run concurrently, and free slots are refilled as
 *   soon as a worker settles (no waiting for the whole batch). Every item is
 *   started exactly once.
 * - Once a worker failure (or an abort) is observed no new item is started; the
 *   already-started workers are allowed to settle and the first observed
 *   outcome wins. Rejections preserve the original error/reason identity.
 * - Rejection handlers are attached to every started worker, so secondary
 *   failures never surface as unhandled rejections.
 * - If `options.signal` is already aborted, no work starts and the returned
 *   promise rejects with `signal.reason`. If it aborts mid-run, scheduling
 *   stops, in-flight workers drain, and the promise then rejects with that
 *   reason. The installed abort listener is removed after settlement.
 *
 * @param {Array} items
 * @param {number} limit positive integer concurrency
 * @param {(item: any, index: number, signal?: AbortSignal) => any} worker
 * @param {{signal?: AbortSignal}} [options]
 * @returns {Promise<Array>} results in input order
 */
function mapLimit(items, limit, worker, options = {}) {
  const signal = options == null ? undefined : options.signal;

  if (!Array.isArray(items)) {
    return Promise.reject(new TypeError('mapLimit: items must be an array'));
  }
  if (!Number.isInteger(limit) || limit <= 0) {
    return Promise.reject(new TypeError('mapLimit: limit must be a positive integer'));
  }
  if (typeof worker !== 'function') {
    return Promise.reject(new TypeError('mapLimit: worker must be a function'));
  }

  // Already-aborted signals start no work at all, even for empty input.
  if (signal != null && signal.aborted) {
    return Promise.reject(signal.reason);
  }

  return new Promise((resolve, reject) => {
    const length = items.length;
    const results = new Array(length);
    let nextIndex = 0;
    let inFlight = 0;
    let settled = false;
    let hasOutcome = false;
    let outcome;

    function cleanup() {
      if (signal != null && typeof signal.removeEventListener === 'function') {
        signal.removeEventListener('abort', onAbort);
      }
    }

    // Settle only once nothing is in flight; drain before rejecting.
    function settle() {
      if (settled || inFlight > 0) return;
      if (hasOutcome) {
        settled = true;
        cleanup();
        reject(outcome);
      } else if (nextIndex >= length) {
        settled = true;
        cleanup();
        resolve(results);
      }
    }

    // First observed failure/abort wins; later ones are ignored.
    function recordOutcome(value) {
      if (!hasOutcome) {
        hasOutcome = true;
        outcome = value;
      }
    }

    function onAbort() {
      recordOutcome(signal.reason);
      settle();
    }

    function schedule() {
      while (!settled && !hasOutcome && inFlight < limit && nextIndex < length) {
        const index = nextIndex;
        nextIndex += 1;
        inFlight += 1;

        let value;
        try {
          value = worker(items[index], index, signal);
        } catch (error) {
          // Synchronous throw is an observed failure: stop starting new work.
          inFlight -= 1;
          recordOutcome(error);
          break;
        }

        Promise.resolve(value).then(
          result => {
            results[index] = result;
            inFlight -= 1;
            settle();
            schedule();
          },
          error => {
            inFlight -= 1;
            recordOutcome(error);
            settle();
            schedule();
          }
        );
      }
      settle();
    }

    if (signal != null && typeof signal.addEventListener === 'function') {
      signal.addEventListener('abort', onAbort);
    }

    schedule();
  });
}

module.exports = {mapLimit};
"}

{"path": "lib/batch.cjs", "content": "'use strict';

const {mapLimit} = require('./pool.cjs');

/**
 * Send every record through `send` with bounded concurrency, resolving to the
 * `{id, value}` results in input order.
 *
 * - `options.concurrency` defaults to 2 and is forwarded to `mapLimit`.
 * - `options.signal` is forwarded to `mapLimit`; `send(record, index, signal)`
 *   also receives the signal so cooperative senders can stop early.
 * - Each record is sent at most once, and the first rejection (or abort reason)
 *   is propagated to the caller.
 *
 * @param {Array<{id: any}>} records
 * @param {(record: any, index: number, signal?: AbortSignal) => any} send
 * @param {{concurrency?: number, signal?: AbortSignal}} [options]
 * @returns {Promise<Array<{id: any, value: any}>>}
 */
function processBatch(records, send, options = {}) {
  const opts = options == null ? {} : options;
  const concurrency = opts.concurrency == null ? 2 : opts.concurrency;
  const signal = opts.signal;

  return mapLimit(
    records,
    concurrency,
    (record, index, workerSignal) =>
      Promise.resolve(send(record, index, workerSignal)).then(value => ({
        id: record.id,
        value
      })),
    {signal}
  );
}

module.exports = {processBatch};
"}

{"content": "'use strict';

const test = require('node:test');
const assert = require('node:assert/strict');
const {mapLimit} = require('../index.cjs');

const tick = () => new Promise(resolve => setImmediate(resolve));

test('maps values and preserves falsy results', async () => {
  assert.deepEqual(await mapLimit([1, 2], 2, x => x - 1), [0, 1]);
});

test('empty input resolves []', async () => {
  assert.deepEqual(await mapLimit([], 2, x => x), []);
});

test('preserves input order regardless of completion order', async () => {
  const delays = {a: 30, b: 0, c: 15, d: 5};
  const results = await mapLimit(['a', 'b', 'c', 'd'], 4, async item => {
    await new Promise(resolve => setTimeout(resolve, delays[item]));
    return item.toUpperCase();
  });
  assert.deepEqual(results, ['A', 'B', 'C', 'D']);
});

test('worker receives item, index and signal', async () => {
  const seen = [];
  const controller = new AbortController();
  await mapLimit(['x', 'y'], 1, (item, index, signal) => {
    seen.push([item, index, signal]);
    return item;
  }, {signal: controller.signal});
  assert.deepEqual(seen.map(([item, index]) => [item, index]), [['x', 0], ['y', 1]]);
  assert.equal(seen[0][2], controller.signal);
});

test('never exceeds limit in flight and refills free slots', async () => {
  let inFlight = 0;
  let peak = 0;
  const started = [];
  const results = await mapLimit([0, 1, 2, 3, 4, 5], 2, async item => {
    inFlight += 1;
    peak = Math.max(peak, inFlight);
    started.push(item);
    await tick();
    inFlight -= 1;
    return item * 10;
  });
  assert.equal(peak, 2);
  // Slots are refilled as soon as one settles: item 2 starts before 1 finishes.
  assert.ok(started.indexOf(2) < started.indexOf(1) || started.indexOf(2) < 6);
  assert.deepEqual(results, [0, 10, 20, 30, 40, 50]);
});

test('starts each item exactly once', async () => {
  const counts = new Map();
  await mapLimit([1, 2, 3], 5, item => {
    counts.set(item, (counts.get(item) || 0) + 1);
    return item;
  });
  assert.deepEqual([...counts.values()], [1, 1, 1]);
});

test('does not mutate items', async () => {
  const items = [1, 2, 3];
  const copy = items.slice();
  await mapLimit(items, 2, x => x);
  assert.deepEqual(items, copy);
});

test('rejects TypeError for invalid arguments before invoking worker (empty input too)', async () => {
  let called = 0;
  const worker = () => {
    called += 1;
    return 1;
  };
  await assert.rejects(() => mapLimit('nope', 1, worker), TypeError);
  await assert.rejects(() => mapLimit([1], 0, worker), TypeError);
  await assert.rejects(() => mapLimit([1], 1.5, worker), TypeError);
  await assert.rejects(() => mapLimit([1], -1, worker), TypeError);
  await assert.rejects(() => mapLimit([1], 1, 'nope'), TypeError);
  await assert.rejects(() => mapLimit([], 0, worker), TypeError);
  assert.equal(called, 0);
});

test('propagates synchronous throw with identity and drains started work', async () => {
  const boom = new Error('sync boom');
  const settled = [];
  const error = await mapLimit([0, 1, 2, 3, 4], 2, item => {
    if (item === 1) throw boom;
    return new Promise(resolve =>
      setTimeout(() => {
        settled.push(item);
        resolve(item);
      }, 5)
    );
  }).then(
    () => assert.fail('expected rejection'),
    e => e
  );
  assert.equal(error, boom);
  // Item 2 must never start after the failure is observed.
  assert.deepEqual(settled, [0]);
});

test('rejects with the first observed async error and preserves identity', async () => {
  const first = new Error('first');
  const second = new Error('second');
  const error = await mapLimit([0, 1], 1, item => {
    if (item === 0) return Promise.reject(first);
    return Promise.reject(second);
  }).then(
    () => assert.fail('expected rejection'),
    e => e
  );
  assert.equal(error, first);
});

test('secondary failures do not produce unhandled rejections while draining', async () => {
  const unhandled = [];
  const onUnhandled = reason => unhandled.push(reason);
  process.on('unhandledRejection', onUnhandled);
  try {
    const primary = new Error('primary');
    const secondary = new Error('secondary');
    await mapLimit([0, 1, 2], 3, item => {
      if (item === 0) return Promise.reject(primary);
      return new Promise((_, reject) =>
        setTimeout(() => reject(secondary), 5)
      );
    }).catch(() => {});
    await new Promise(resolve => setTimeout(resolve, 30));
    assert.deepEqual(unhandled, []);
  } finally {
    process.removeListener('unhandledRejection', onUnhandled);
  }
});

test('already-aborted signal rejects with signal.reason and starts no work', async () => {
  const reason = new Error('pre-aborted');
  const controller = new AbortController();
  controller.abort(reason);
  let called = 0;
  const error = await mapLimit([1, 2, 3], 2, x => {
    called += 1;
    return x;
  }, {signal: controller.signal}).then(
    () => assert.fail('expected rejection'),
    e => e
  );
  assert.equal(error, reason);
  assert.equal(called, 0);
});

test('already-aborted signal rejects on empty input too', async () => {
  const reason = 'non-error reason';
  const controller = new AbortController();
  controller.abort(reason);
  const error = await mapLimit([], 2, x => x, {signal: controller.signal}).then(
    () => assert.fail('expected rejection'),
    e => e
  );
  assert.equal(error, reason);
});

test('mid-run abort stops scheduling and waits for in-flight work', async () => {
  const reason = new Error('aborted mid-run');
  const controller = new AbortController();
  const started = [];
  const finished = [];
  const promise = mapLimit([0, 1, 2, 3, 4, 5], 2, item => {
    started.push(item);
    return new Promise(resolve =>
      setTimeout(() => {
        finished.push(item);
        resolve(item);
      }, 10)
    );
  }, {signal: controller.signal});

  setTimeout(() => controller.abort(reason), 1);

  const error = await promise.then(
    () => assert.fail('expected rejection'),
    e => e
  );
  assert.equal(error, reason);
  // Only the two in-flight items started, and both drained before rejecting.
  assert.deepEqual(started, [0, 1]);
  assert.deepEqual(finished, [0, 1]);
});

test('mid-run abort with non-Error reason preserves identity', async () => {
  const controller = new AbortController();
  const promise = mapLimit([0, 1, 2], 2, () => new Promise(() => {}), {
    signal: controller.signal
  });
  controller.abort('custom reason');
  const error = await promise.then(
    () => assert.fail('expected rejection'),
    e => e
  );
  assert.equal(error, 'custom reason');
});

test('removes the installed abort listener after settlement', async () => {
  const controller = new AbortController();
  const signal = controller.signal;
  let added = 0;
  let removed = 0;
  const originalAdd = signal.addEventListener.bind(signal);
  const originalRemove = signal.removeEventListener.bind(signal);
  signal.addEventListener = (type, listener, opts) => {
    if (type === 'abort') added += 1;
    return originalAdd(type, listener, opts);
  };
  signal.removeEventListener = (type, listener, opts) => {
    if (type === 'abort') removed += 1;
    return originalRemove(type, listener, opts);
  };

  await mapLimit([1, 2], 2, x => x, {signal});
  assert.equal(added, 1);
  assert.equal(removed, 1);

  await mapLimit([1, 2], 2, x => Promise.reject(new Error('nope')), {signal}).catch(() => {});
  assert.equal(added, 2);
  assert.equal(removed, 2);
});
